After weeks of pain I managed to create my own physics script that I attached to a character body 3d. It does not use angular momentum but it still works the way I need it to.

```gdscript
extends CharacterBody3D

@export var Mass := 1.0
@export var Velocity := Vector2(0,0)
@export var ForceOfGravity := Vector2(0,-9.8)
@export var FrictionCoefficient := .5
@export var AirResistance := .001
@export var IsStatic := false
@export_range(0.0,1.0) var ForceTransfer := 0.5

var ShapeCast = ShapeCast3D.new()

func _ready():
	add_child(ShapeCast)
	ShapeCast.shape = GetCollisionShape()

func _process(delta):

	pass

	ApplyForce(Mass,ForceOfGravity*delta)

	Move(delta)


func ApplyForce(AppliedMass:=1.0,AppliedVelocity:=Vector2(0,0)):

	Velocity += AppliedMass*AppliedVelocity/Mass

var VelocityDelta = 1
var Collisions = 0

func Move(delta):

	VelocityDelta = 1

	if TestCollision(delta) && VelocityDelta > 0 && Collisions < 10:
		Collisions += 1
		Move(delta)
		return

	Collisions = 0

func TestCollision(delta):

	var PointBeforeCollision = YZToVec2(global_position)

	move_and_collide(Vec2ToYZ(Velocity*VelocityDelta*delta))

	ShapeCast.target_position = Vec2ToYZ(RotatePoint(Velocity*VelocityDelta*delta,global_rotation.x))*Vector3(1,1,-1)
	ShapeCast.force_shapecast_update()

	if ShapeCast.is_colliding():

		var CollisionNormal = YZToVec2(ShapeCast.get_collision_normal(0))

		#Gets time to destination to make movement after collision more accurate
		VelocityDelta -= GetTimeToDestination(YZToVec2(global_position),PointBeforeCollision,Velocity*VelocityDelta)

		#Adds Collision force
		TransferMomentum(CollisionNormal,ShapeCast.get_collider(0))

		return true #Was collision
	return false #was no collision


func TransferMomentum(Normal,InvolvedCollider):

